@using sv_5fa1b5f3b2544707a52c49c2c7f9ba24.Models

<div class="d-flex align-items-center justify-content-between mb-4 step-indicator">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var step = i + 1;
        var isActive = step == CurrentStep;
        var isCompleted = CompletedSteps.Contains(step);

        <div class="d-flex align-items-center flex-fill">
            <button type="button"
                    class="btn btn-sm rounded-circle step-circle @(isActive ? "btn-primary" : isCompleted ? "btn-success" : "btn-outline-secondary")"
                    disabled="@(!isCompleted || isActive)"
                    @onclick="() => HandleClick(step)">
                @if (isCompleted && !isActive)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@step</span>
                }
            </button>
            <span class="ms-2 small @(isActive ? "fw-bold text-primary" : isCompleted ? "text-success" : "text-muted")">
                @StepNames[i]
            </span>

            @if (i < StepNames.Length - 1)
            {
                <div class="flex-fill border-top mx-3 @(isCompleted ? "border-success" : "border-secondary")" style="opacity: @(isCompleted ? 1 : 0.3);"></div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly string[] StepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private async Task HandleClick(int step)
    {
        if (CompletedSteps.Contains(step))
            await OnStepClicked.InvokeAsync(step);
    }
}

.step-circle {
    width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.85rem;
    padding: 0;
    flex-shrink: 0;
}

@using sv_5fa1b5f3b2544707a52c49c2c7f9ba24.Models

<h4 class="mb-3">Personal Information</h4>

<div class="mb-3">
    <label class="form-label">Full Name <span class="text-danger">*</span></label>
    <input type="text" class="form-control @FieldClass(Model.FullName)" @bind="Model.FullName" />
    @if (_showErrors && string.IsNullOrWhiteSpace(Model.FullName))
    {
        <div class="invalid-feedback d-block">Full name is required.</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Email <span class="text-danger">*</span></label>
    <input type="email" class="form-control @FieldClass(Model.Email) @(_emailError != null ? "is-invalid" : "")"
           @bind="Model.Email" />
    @if (_showErrors && string.IsNullOrWhiteSpace(Model.Email))
    {
        <div class="invalid-feedback d-block">Email is required.</div>
    }
    else if (_emailError != null)
    {
        <div class="invalid-feedback d-block">@_emailError</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Phone <span class="text-danger">*</span></label>
    <input type="tel" class="form-control @FieldClass(Model.Phone)" @bind="Model.Phone" />
    @if (_showErrors && string.IsNullOrWhiteSpace(Model.Phone))
    {
        <div class="invalid-feedback d-block">Phone is required.</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Address <span class="text-danger">*</span></label>
    <textarea class="form-control @FieldClass(Model.Address)" rows="2" @bind="Model.Address"></textarea>
    @if (_showErrors && string.IsNullOrWhiteSpace(Model.Address))
    {
        <div class="invalid-feedback d-block">Address is required.</div>
    }
</div>

<div class="d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@_validating">
        @if (_validating)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Next
    </button>
</div>

@code {
    [Parameter] public PersonalInfoModel Model { get; set; } = new();
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public required Func<string, Task<bool>> ValidateEmail { get; set; }

    private bool _showErrors;
    private string? _emailError;
    private bool _validating;

    private string FieldClass(string value) =>
        _showErrors && string.IsNullOrWhiteSpace(value) ? "is-invalid" : "";

    private async Task HandleNext()
    {
        _showErrors = true;
        _emailError = null;

        if (string.IsNullOrWhiteSpace(Model.FullName)
            || string.IsNullOrWhiteSpace(Model.Email)
            || string.IsNullOrWhiteSpace(Model.Phone)
            || string.IsNullOrWhiteSpace(Model.Address))
            return;

        _validating = true;
        try
        {
            var isValid = await ValidateEmail(Model.Email);
            if (!isValid)
            {
                _emailError = "Please enter a valid email address.";
                return;
            }
            await OnNext.InvokeAsync();
        }
        finally
        {
            _validating = false;
        }
    }
}

@using sv_5fa1b5f3b2544707a52c49c2c7f9ba24.Models

<h4 class="mb-3">Work History</h4>

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    <WorkEntryForm Entry="Entries[index]"
                   Index="index"
                   CanRemove="Entries.Count > 1"
                   OnRemove="() => RemoveEntry(index)" />
}

<button type="button" class="btn btn-outline-primary btn-sm mb-4" @onclick="AddEntry">
    + Add Another Position
</button>

@if (_showErrors)
{
    <div class="alert alert-danger">Please fill in company name, job title, and start date for all positions.</div>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-outline-secondary" @onclick="() => OnBack.InvokeAsync()">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public List<WorkEntryModel> Entries { get; set; } = new();
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private bool _showErrors;

    private void AddEntry() => Entries.Add(new WorkEntryModel());

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        _showErrors = Entries.Any(e =>
            string.IsNullOrWhiteSpace(e.Company)
            || string.IsNullOrWhiteSpace(e.Title)
            || e.StartDate == null);

        if (!_showErrors)
            await OnNext.InvokeAsync();
    }
}

