{"file_text": "@using sv_5fa1b5f3b2544707a52c49c2c7f9ba24.Models

<h4 class="mb-3">Personal Information</h4>

<div class="mb-3">
    <label class="form-label">Full Name <span class="text-danger">*</span></label>
    <input type="text" class="form-control @FieldClass(Model.FullName)" @bind="Model.FullName" />
    @if (_showErrors && string.IsNullOrWhiteSpace(Model.FullName))
    {
        <div class="invalid-feedback d-block">Full name is required.</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Email <span class="text-danger">*</span></label>
    <input type="email" class="form-control @FieldClass(Model.Email) @(_emailError != null ? "is-invalid" : "")"
           @bind="Model.Email" />
    @if (_showErrors && string.IsNullOrWhiteSpace(Model.Email))
    {
        <div class="invalid-feedback d-block">Email is required.</div>
    }
    else if (_emailError != null)
    {
        <div class="invalid-feedback d-block">@_emailError</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Phone <span class="text-danger">*</span></label>
    <input type="tel" class="form-control @FieldClass(Model.Phone)" @bind="Model.Phone" />
    @if (_showErrors && string.IsNullOrWhiteSpace(Model.Phone))
    {
        <div class="invalid-feedback d-block">Phone is required.</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Address <span class="text-danger">*</span></label>
    <textarea class="form-control @FieldClass(Model.Address)" rows="2" @bind="Model.Address"></textarea>
    @if (_showErrors && string.IsNullOrWhiteSpace(Model.Address))
    {
        <div class="invalid-feedback d-block">Address is required.</div>
    }
</div>

<div class="d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@_validating">
        @if (_validating)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Next
    </button>
</div>

@code {
    [Parameter] public PersonalInfoModel Model { get; set; } = new();
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public required Func<string, Task<bool>> ValidateEmail { get; set; }

    private bool _showErrors;
    private string? _emailError;
    private bool _validating;

    private string FieldClass(string value) =>
        _showErrors && string.IsNullOrWhiteSpace(value) ? "is-invalid" : "";

    private async Task HandleNext()
    {
        _showErrors = true;
        _emailError = null;

        if (string.IsNullOrWhiteSpace(Model.FullName)
            || string.IsNullOrWhiteSpace(Model.Email)
            || string.IsNullOrWhiteSpace(Model.Phone)
            || string.IsNullOrWhiteSpace(Model.Address))
            return;

        _validating = true;
        try
        {
            var isValid = await ValidateEmail(Model.Email);
            if (!isValid)
            {
                _emailError = "Please enter a valid email address.";
                return;
            }
            await OnNext.InvokeAsync();
        }
        finally
        {
            _validating = false;
        }
    }
}
