@using sv_5fa1b5f3b2544707a52c49c2c7f9ba24.Models

<h4 class="mb-3">Work History</h4>

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    <WorkEntryForm Entry="Entries[index]"
                   Index="index"
                   CanRemove="Entries.Count > 1"
                   OnRemove="() => RemoveEntry(index)" />
}

<button type="button" class="btn btn-outline-primary btn-sm mb-4" @onclick="AddEntry">
    + Add Another Position
</button>

@if (_showErrors)
{
    <div class="alert alert-danger">Please fill in company name, job title, and start date for all positions.</div>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-outline-secondary" @onclick="() => OnBack.InvokeAsync()">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public List<WorkEntryModel> Entries { get; set; } = new();
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private bool _showErrors;

    private void AddEntry() => Entries.Add(new WorkEntryModel());

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        _showErrors = Entries.Any(e =>
            string.IsNullOrWhiteSpace(e.Company)
            || string.IsNullOrWhiteSpace(e.Title)
            || e.StartDate == null);

        if (!_showErrors)
            await OnNext.InvokeAsync();
    }
}

